+/// Returns `a << n` truncated to 256 bits, for `n < 256`.
+#[inline(always)]
+fn shl_limbs(mut a: [u64; 4], mut n: u32) -> [u64; 4] {
+    while n >= 64 {
+        a = [0, a[0], a[1], a[2]];
+        n -= 64;
+    }
+    if n == 0 {
+        return a;
+    }
+    [
+        a[0] << n,
+        (a[1] << n) | (a[0] >> (64 - n)),
+        (a[2] << n) | (a[1] >> (64 - n)),
+        (a[3] << n) | (a[2] >> (64 - n)),
+    ]
+}
